    existing[place] = ex_resp.get('exists') if isinstance(ex_resp, dict) else ex_resp
    if not existing[place]:
        apis.file_system.create_directory(access_token=fs_access_token, directory_path=dir_path)
        created[place] = True
    else:
        created[place] = False

print('dir_exists', existing)
print('dir_created', created)

